function mediaSecret(){
 const configured=String(process.env.KV_MEDIA_KEY_SECRET||'').trim();
 if(configured)return crypto.createHash('sha256').update(configured).digest();
 if(LOCAL_DEMO)return crypto.createHash('sha256').update(String(process.env.KV_ADMIN_KEY||'katha-vistaar-local-demo')).digest();
 throw new Error('media_key_secret_required');
}
function encryptMediaKey(key){
 const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',mediaSecret(),iv),enc=Buffer.concat([cipher.update(key),cipher.final()]);
 return {iv:iv.toString('base64'),tag:cipher.getAuthTag().toString('base64'),data:enc.toString('base64')};
}
function decryptMediaKey(box){
 const decipher=crypto.createDecipheriv('aes-256-gcm',mediaSecret(),Buffer.from(box.iv,'base64'));decipher.setAuthTag(Buffer.from(box.tag,'base64'));return Buffer.concat([decipher.update(Buffer.from(box.data,'base64')),decipher.final()]);
}
function safeMediaId(v){const x=String(v||'');return /^[a-zA-Z0-9_-]{1,120}$/.test(x)?x:null;}
