 const row={id:'MSG-'+crypto.randomBytes(5).toString('hex').toUpperCase(),target:String(target),type,purpose,language:String(language||'en').toLowerCase(),createdAt:now(),mode:cap.enabled?'external':(LOCAL_DEMO?'local_test_outbox':'internal_otp_store'),delivered:false};
