function publishContract({user,c,status,publishAt=null,idempotencyKey=null,source='creator',requestBody=null}){
  const requested=String(status||'published').toLowerCase();
  if(!['published','scheduled'].includes(requested)) return {ok:false,statusCode:400,error:'invalid_publish_status'};
  if(!creatorRightAllowed(c,'publish')) return {ok:false,statusCode:403,error:'creator_publish_right_revoked'};
  if(c.type==='story'&&source!=='creator_create'){
    let storyLanguage;
    try{storyLanguage=assertStoryLanguage(c.language||c.studioProject?.language||'en');}
    catch(e){return {ok:false,statusCode:422,error:e.code||'unsupported_story_language',supportedLanguages:e.supported};}
    c.language=storyLanguage;
    const readiness=storyStudio.readiness(c);
    if(!readiness.ready) return {ok:false,statusCode:409,error:'story_not_ready_for_publish',readiness};
    if(c.storyPublicationApproval!==true) return {ok:false,statusCode:409,error:'story_creator_approval_required',readiness};
    const checklist=storyStudio.publishingChecklist(c);
    if(!checklist.ready) return {ok:false,statusCode:409,error:'story_publishing_checklist_failed',publishingChecklist:checklist};
  }
  const key=idempotencyKey?`${user.id}:${c.id}:${String(idempotencyKey).slice(0,160)}`:null;
  if(key&&publishOperations.has(key)) return {ok:true,replayed:true,operation:publishOperations.get(key),content:c};
  const title=String(c.title||'').trim();
  if(!title) return {ok:false,statusCode:400,error:'publish_title_required'};
  let scheduledAt=publishAt||c.publishAt||null;
  if(requested==='scheduled'&&!scheduledAt)return {ok:false,statusCode:400,error:'publish_at_required'};
  const before={status:c.status,approval:c.approval,publishAt:c.publishAt};
  c.publishAt=scheduledAt;
  const moderationResult=moderateOnPublish(user,c,requestBody||{status:requested});
  const operation={id:id(),contentId:c.id,userId:user.id,requestedStatus:requested,source,before,after:{status:c.status,approval:c.approval,publishAt:c.publishAt},createdAt:now(),result:moderationResult.status||c.status};
  if(key) publishOperations.set(key,operation);
  coreAudit.record({actor:user.userId,action:'content_publish_contract',resourceType:'content',resourceId:c.id,result:operation.result,requestedStatus:requested,source,operationId:operation.id});
  notifyUser(user.id,{category:'content',type:requested==='scheduled'?'content_scheduled':'content_published',titleKey:requested==='scheduled'?'notification_content_scheduled':'notification_content_processed',bodyKey:requested==='scheduled'?'notification_content_scheduled_body':moderationResult.status==='pending_review'?'notification_content_pending_body':moderationResult.status==='published'?'notification_content_published_body':'notification_content_not_published_body',deepLink:'/writing'});
  persistence?.save(persistenceMaps,true);
  return {ok:moderationResult.ok,replayed:false,status:moderationResult.status,approval:moderationResult.approval,operation,content:c,publication:moderationResult};
}
function finalizeAdminPublication(authCtx,c,decision){
  if(decision!=='approve')return {ok:false,statusCode:400,error:'invalid_decision'};
  if(c.approval?.state!=='pending_admin')return {ok:false,statusCode:404,error:'pending_review_not_found'};
  c.status='published';c.publishAt=null;c.approval={state:'approved',source:'admin',reviewedAt:now(),adminRole:authCtx.role};c.updatedAt=now();
  coreAudit.record({actor:authCtx.adminId,action:'content_publish_admin_approved',resourceType:'content',resourceId:c.id,result:'published',adminRole:authCtx.role});
  const owner=users.get(c.ownerId);if(owner)notifyUser(owner.id,{category:'content',type:'content_published',titleKey:'notification_content_approved',bodyKey:'notification_content_approved_body',deepLink:'/writing'});
  persistence?.save(persistenceMaps,true);return {ok:true,content:c};
}

