function ensureCoinLots(user){const rows=coinLotRows(user);const total=rows.reduce((n,x)=>n+Math.max(0,Number(x.coinsRemaining)||0),0);const balance=Math.max(0,Math.floor(Number(user?.coins||0)));if(balance>total)addCoinLot(user,{source:'legacy_or_unattributed',coins:balance-total,paidAmountInr:0,unitValueInr:0,provenance:'legacy_balance_zero_cash_basis'});return coinLotRows(user);}
function consumeCoinLots(user,amount){const qty=Math.floor(Number(amount)||0);if(!user||qty<=0)throw Object.assign(new Error('invalid_coin_lot_consumption'),{code:'invalid_coin_lot_consumption'});ensureCoinLots(user);const rows=coinLotRows(user);const available=rows.reduce((n,x)=>n+Math.max(0,Number(x.coinsRemaining)||0),0);if(available<qty)throw Object.assign(new Error('coin_lot_provenance_unavailable'),{code:'coin_lot_provenance_unavailable'});let remaining=qty;const consumed=[];for(const row of rows){if(remaining<=0)break;const take=Math.min(remaining,Math.max(0,Number(row.coinsRemaining)||0));if(take<=0)continue;const originalCoins=Math.max(0,Number(row.originalCoins)||0);const ratio=originalCoins>0?take/originalCoins:0;row.coinsRemaining-=take;consumed.push({lotId:row.id,source:row.source,sourceTransactionId:row.sourceTransactionId,coins:take,originalCoins,paidAmountInr:Number((Number(row.paidAmountInr||0)*ratio).toFixed(2)),lotPaidAmountInr:Number(row.paidAmountInr||0),unitValueInr:Number(row.unitValueInr||0),provenance:row.provenance,rootSourceTransactionId:row.rootSourceTransactionId||row.sourceTransactionId||null,createdAt:row.createdAt});remaining-=take;}coinLots.set(String(user.id),rows.filter(x=>Number(x.coinsRemaining||0)>0));return consumed;}
function restoreCoinLots(user,allocations){if(!user)return;const rows=coinLotRows(user);for(const a of allocations||[]){const existing=rows.find(x=>x.id===String(a.lotId));if(existing){existing.coinsRemaining=Math.min(Number(existing.originalCoins||0),Number(existing.coinsRemaining||0)+Number(a.coins||0));continue;}rows.push({id:String(a.lotId||`CLOT-${crypto.randomBytes(7).toString('hex').toUpperCase()}`),source:String(a.source||'restored'),sourceTransactionId:a.sourceTransactionId?String(a.sourceTransactionId):null,coinsRemaining:Math.max(0,Math.floor(Number(a.coins)||0)),originalCoins:Math.max(0,Math.floor(Number(a.originalCoins||a.coins)||0)),paidAmountInr:Math.max(0,Number(a.lotPaidAmountInr??a.paidAmountInr??0)),unitValueInr:Math.max(0,Number(a.unitValueInr||0)),provenance:String(a.provenance||'restored_coin_lot'),rootSourceTransactionId:a.rootSourceTransactionId?String(a.rootSourceTransactionId):(a.sourceTransactionId?String(a.sourceTransactionId):null),createdAt:a.createdAt||now()});}coinLots.set(String(user.id),rows.filter(x=>Number(x.coinsRemaining||0)>0));return coinLotRows(user);}
function addConsumedCoinLots(user,allocations,transferMeta={}){for(const a of allocations||[])addCoinLot(user,{source:a.source,sourceTransactionId:a.sourceTransactionId,coins:a.coins,paidAmountInr:a.paidAmountInr,unitValueInr:a.unitValueInr,provenance:a.provenance||transferMeta.provenance||'transferred_coin_lot',rootSourceTransactionId:a.rootSourceTransactionId||a.sourceTransactionId||null});}
function coinEconomicBasisInr(allocations){return Number((allocations||[]).reduce((n,x)=>n+Number(x.paidAmountInr||0),0).toFixed(2));}
function coinLotRoot(row){return String(row?.rootSourceTransactionId||row?.sourceTransactionId||'');}
function rootCoinLots(){const out=[];for(const [uid,rows] of coinLots.entries())for(const row of (Array.isArray(rows)?rows:[]))if(row&&Number(row.coinsRemaining||0)>0)out.push({userId:String(uid),row});return out;}
function removeRootCoinLots(user,root){const rows=coinLotRows(user),removed=[];for(const row of rows){if(coinLotRoot(row)!==String(root)||Number(row.coinsRemaining||0)<=0)continue;removed.push({...row,coinsRemoved:Number(row.coinsRemaining||0)});row.coinsRemaining=0;}coinLots.set(String(user.id),rows.filter(x=>Number(x.coinsRemaining||0)>0));return removed;}
function revokeCoinDownstreamEffects(root,actor){const affected=[];for(const [k,rows] of coinTransactions.entries()){for(const row of (Array.isArray(rows)?rows:[])){const prov=Array.isArray(row?.lotProvenance)?row.lotProvenance:[];if(!prov.some(x=>String(x?.rootSourceTransactionId||x?.sourceTransactionId||'')===String(root)))continue;affected.push(row);if(row.royaltyEventId&&row.royaltyReversalStatus!=='reversed'){const rr=royaltyEngine.reverse(row.id,'coin_purchase_refund');if(rr&&rr.ok!==false){row.royaltyReversalStatus='reversed';row.royaltyReversalEventId=rr.id;row.royaltyReversalAt=now();}}if(row.type==='novel_unlock'&&row.contentId){const u=users.get(String(row.from||row.userId||''));const c=content.get(String(row.contentId));if(u&&c){const sid=c.seriesId||c.id,p=u.readerAccess?.novel?.[sid];if(p&&Array.isArray(p.unlockedParts)){p.unlockedParts=p.unlockedParts.filter(n=>Number(n)!==Number(c.partNumber));}}row.status='reversed';row.reversalReason='coin_purchase_refund';}if(row.type==='sticker_purchase'){const u=users.get(String(row.userId||row.from||''));if(u){const lots=stickerLots(u,row.sticker);u.stickerInventory[row.sticker]=lots.filter(x=>String(x.sourceTransactionId||'')!==String(row.id));if(!u.stickerInventory[row.sticker].length)delete u.stickerInventory[row.sticker];}row.status='reversed';row.reversalReason='coin_purchase_refund';}row.coinPurchaseRefunded=true;row.coinPurchaseRefundedAt=now();}setMap(coinTransactions,k,rows);}return affected;}
function refundCoinPurchase({transactionId,reason='coin_purchase_refund',actor='system',authoritativeConfirmed=false}={}){const txId=String(transactionId||'');let purchase=null,key=null;for(const [k,rows] of coinTransactions.entries()){const found=(Array.isArray(rows)?rows:[]).find(x=>String(x?.id||'')===txId&&x?.type==='coin_purchase');if(found){purchase=found;key=k;break;}}if(!purchase)return {ok:false,status:404,error:'coin_purchase_not_found'};if(purchase.status==='refunded'||purchase.refundStatus==='refunded')return {ok:true,status:200,replayed:true,transaction:purchase};if(purchase.status!=='paid')return {ok:false,status:409,error:'coin_purchase_not_settled'};if(authoritativeConfirmed!==true)return {ok:false,status:409,error:'authoritative_refund_confirmation_required'};const root=String(purchase.id);const descendants=rootCoinLots().filter(x=>coinLotRoot(x.row)===root);const totalIssued=Number(purchase.coins||0);const available=descendants.reduce((n,x)=>n+Number(x.row.coinsRemaining||0),0);const consumed=Math.max(0,totalIssued-available);const affected=revokeCoinDownstreamEffects(root,actor);let clawed=0;for(const uid of new Set(descendants.map(x=>x.userId))){const u=users.get(uid);if(!u)continue;const removed=removeRootCoinLots(u,root);const n=removed.reduce((a,x)=>a+Number(x.coinsRemoved||0),0);if(n>0){if(Number(u.coins||0)<n)return {ok:false,status:409,error:'coin_refund_balance_invariant_failed'};u.coins=Number(u.coins||0)-n;clawed+=n;}}
if(clawed!==available)return {ok:false,status:409,error:'coin_refund_lineage_mismatch'};
purchase.refundStatus='refunded';purchase.refundedAt=now();purchase.refundReason=String(reason).slice(0,500);purchase.refundCoinsClawedBack=clawed;purchase.refundConsumedCoins=consumed;purchase.refundDownstreamEffects=affected.length;purchase.refundAuthoritative=true;purchase.status='refunded';purchase.refundActor=actor;purchase.updatedAt=now();setMap(coinTransactions,key,(coinTransactions.get(key)||[]).map(x=>x?.id===purchase.id?purchase:x));coreAudit.record({actor,action:'coin_purchase_refund',resourceType:'coin_purchase',resourceId:purchase.id,result:'refunded',coinsIssued:totalIssued,coinsClawedBack:clawed,consumedCoins:consumed,downstreamEffects:affected.length,reason:String(reason).slice(0,500)});const u=users.get(String(purchase.userId||''));if(u)notifyUser(u.id,{category:'payment',type:'coin_purchase_refunded',titleKey:'notification_coin_refunded',bodyKey:'notification_coin_refunded_body'});persistence?.save(persistenceMaps,true);return {ok:true,status:200,replayed:false,transaction:purchase,coinsClawedBack:clawed,consumedCoins:consumed,downstreamEffects:affected.length};}
function findRoyaltySource(transactionId){
 const idv=String(transactionId||'');
 for(const [k,v] of subscriptionPayments.entries()) for(const row of (Array.isArray(v)?v:[v])) if(String(row?.id||'')===idv) return {kind:'subscription',row,key:k,map:subscriptionPayments};
 for(const [k,v] of coinTransactions.entries()) for(const row of (Array.isArray(v)?v:[v])) if(String(row?.id||'')===idv && row?.royaltyEventId) return {kind:'coin',row,key:k,map:coinTransactions};
 for(const [k,v] of stickerTransactions.entries()) for(const row of (Array.isArray(v)?v:[v])) if(String(row?.id||'')===idv) return {kind:'sticker',row,key:k,map:stickerTransactions};
 return null;
}
function reverseRoyaltyForReversedSource(transactionId,reason='source_reversal',actor='system'){
 const source=findRoyaltySource(transactionId); if(!source)return {ok:false,error:'royalty_source_not_found'};
 const rr=royaltyEngine.reverse(transactionId,reason); if(!rr||rr.ok===false)return rr;
 source.row.royaltyReversalStatus='reversed'; source.row.royaltyReversalAt=now(); source.row.royaltyReversalEventId=rr.id; source.row.royaltyRecoveryAmount=Number(rr.netRoyalty||0); source.row.royaltyReversalReason=String(reason).slice(0,500);
 if(source.kind==='subscription') setMap(subscriptionPayments,source.key,(source.map.get(source.key)||[]).map(x=>x?.id===source.row.id?source.row:x)); else setMap(source.map,source.key,source.row);
 coreAudit.record({actor,action:'royalty_reversed',resourceType:'royalty',resourceId:rr.id,result:'reversed',sourceTransactionId:transactionId,sourceType:source.kind,reason:String(reason).slice(0,500)});
 if(source.row.creatorId)notifyUser(source.row.creatorId,{category:'royalty',type:'royalty_reversed',titleKey:'notification_royalty_reversed',bodyKey:'notification_royalty_reversed_body',deepLink:'/account'});
 persistence?.save(persistenceMaps,true); return {ok:true,sourceType:source.kind,source:source.row,royalty:rr};
}
function monthlyMonetizationSummary(user,month){
 const m=/^\d{4}-\d{2}$/.test(String(month||''))?String(month):new Date().toISOString().slice(0,7);
 const start=Date.parse(`${m}-01T00:00:00.000Z`); const end=new Date(new Date(start).setUTCMonth(new Date(start).getUTCMonth()+1)).getTime();
 const inMonth=(at)=>{const t=Date.parse(at||'');return Number.isFinite(t)&&t>=start&&t<end;};
 const coinRows=[...coinTransactions.values()].flatMap(v=>Array.isArray(v)?v:[v]).filter(Boolean).filter(x=>inMonth(x.createdAt||x.at));
 const stickerRows=[...stickerTransactions.values()].flatMap(v=>Array.isArray(v)?v:[v]).filter(Boolean).filter(x=>inMonth(x.createdAt||x.at));
 const subRows=[...subscriptionPayments.values()].flatMap(v=>Array.isArray(v)?v:[v]).filter(Boolean).filter(x=>inMonth(x.createdAt||x.at));
 const royaltyRows=[...royaltyEvents.values()].filter(x=>x?.creatorId===user.id&&inMonth(x.createdAt||x.at));
 const mine=(x)=>String(x.userId||x.from||'')===String(user.id);
 const coinPurchased=coinRows.filter(x=>x.type==='coin_purchase'&&mine(x)&&x.status!=='refunded').reduce((n,x)=>n+Number(x.baseCoins||x.coins||0),0);
 const coinBonus=coinRows.filter(x=>x.type==='coin_purchase'&&mine(x)&&x.status!=='refunded').reduce((n,x)=>n+Math.max(0,Number(x.coins||0)-Number(x.baseCoins||0)),0);
 const coinGifted=coinRows.filter(x=>x.type==='coin_gift'&&String(x.from||'')===String(user.id)&&x.status!=='reversed').reduce((n,x)=>n+Number(x.amount||0),0);
 const coinReceived=coinRows.filter(x=>x.type==='coin_gift'&&String(x.to||'')===String(user.id)&&x.status!=='reversed').reduce((n,x)=>n+Number(x.amount||0),0);
 const unlockSpent=coinRows.filter(x=>x.type==='novel_unlock'&&mine(x)&&x.status!=='reversed').reduce((n,x)=>n+Number(x.amount||0),0);
 const stickerSpent=coinRows.filter(x=>x.type==='sticker_purchase'&&mine(x)&&x.status!=='reversed').reduce((n,x)=>n+Number(x.amount||x.cost||0),0);
 const stickerReceived=stickerRows.filter(x=>String(x.to||'')===String(user.id)&&x.status!=='refunded'&&x.status!=='reversed').reduce((n,x)=>n+Number(x.cost||0),0);
 const reversedCoins=coinRows.filter(x=>mine(x)&&(x.status==='reversed'||x.status==='refunded')).reduce((n,x)=>n+Number(x.amount||x.coins||0),0);
 const reversedStickers=stickerRows.filter(x=>String(x.from||x.userId||'')===String(user.id)&&(x.status==='refunded'||x.status==='reversed')).reduce((n,x)=>n+Number(x.cost||0),0);
 const royaltyAccrued=royaltyRows.filter(x=>!['reversed','refunded'].includes(x.status)).reduce((n,x)=>n+Number(x.netRoyalty||0),0);
 const royaltyReversed=royaltyRows.filter(x=>['reversed','refunded'].includes(x.status)).reduce((n,x)=>n+Number(x.netRoyalty||0),0);
 const subscriptionPaid=subRows.filter(x=>mine(x)&&x.status==='paid').reduce((n,x)=>n+Number(x.amount||0),0);
 return {month,userId:user.id,balance:{coins:Number(user.coins||0),stickers:Object.values(user.stickerInventory||{}).reduce((n,v)=>n+(Array.isArray(v)?v.length:0),0)},coins:{purchased:coinPurchased,bonus:coinBonus,received:coinReceived,gifted:coinGifted,spent:coinGifted+unlockSpent+stickerSpent,adjusted:0,reversed:reversedCoins},stickers:{received:stickerReceived,spent:stickerSpent,adjusted:0,reversed:reversedStickers},subscriptions:{paid:subscriptionPaid},royalty:{accrued:Number(royaltyAccrued.toFixed(2)),reversed:Number(royaltyReversed.toFixed(2)),events:royaltyRows.length},source:'internal_persistent_ledgers',generatedAt:now()};
}

function recordCoinRoyalty({transactionId,creator,allocations,stream,contentId=null,description=''}){const basis=coinEconomicBasisInr(allocations);if(!transactionId||!creator||basis<=0||Number(creator.followers||0)<Number(monetization.get().royalty?.minGenuineFollowers||0))return null;const rr=royaltyEngine.record({gross:basis,tax:0,fees:0,refunds:0,creatorFollowers:Number(creator.followers||0),stream,transactionId,creatorId:creator.id,creatorState:creator.state||creator.creatorState||null,source:'commercial',coinValueInr:Number(monetization.get().stickerCoinRate)});coreAudit.record({actor:'system',action:'royalty_accrued',resourceType:'royalty',resourceId:rr.id,result:'accrued',stream,sourceTransactionId:transactionId,contentId});notifyUser(creator.id,{category:'royalty',type:'royalty_accrued',titleKey:'notification_royalty_accrued',bodyKey:'notification_royalty_accrued_body',bodyParams:{source:description||stream},deepLink:contentId?`/reader?contentId=${encodeURIComponent(contentId)}`:'/account'});return rr;}
const masterAdminPaymentFulfillment=createMasterAdminPaymentFulfillment({requests:masterAdminFulfillments,supply:masterAdminAssetSupply,coinLedger,paymentLedger,coinTransactions,stickerTransactions,users,stickerLots,acquireSticker,monetization,transactionVerifications,coreAudit,now,addCoinLot});
function backupKey(){return String(process.env.KV_BACKUP_ENCRYPTION_KEY||'').trim()}
function encryptBackupAuth(usersList){const key=backupKey();if(!key)return null;const secret=crypto.createHash('sha256').update(key).digest();const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',secret,iv);const data=Buffer.concat([cipher.update(JSON.stringify(usersList),'utf8'),cipher.final()]);return {alg:'AES-256-GCM',iv:iv.toString('base64'),data:data.toString('base64'),tag:cipher.getAuthTag().toString('base64')};}
function decryptBackupAuth(box){const key=backupKey();if(!key||!box)throw new Error('backup_encryption_key_required');const secret=crypto.createHash('sha256').update(key).digest();const decipher=crypto.createDecipheriv('aes-256-gcm',secret,Buffer.from(box.iv,'base64'));decipher.setAuthTag(Buffer.from(box.tag,'base64'));return JSON.parse(Buffer.concat([decipher.update(Buffer.from(box.data,'base64')),decipher.final()]).toString('utf8'));}
function contentEngagement(cid){const rs=listMap(reviews,cid), cs=listMap(comments,cid), ls=listMap(likes,cid);const c=content.get(cid);const base=Number(c?.rating||4.5);const avg=rs.length?Math.round(rs.reduce((a,r)=>a+r.rating,0)/rs.length*100)/100:base;return {rating:avg,ratingCount:rs.length||Number(c?.ratingCount||0),commentCount:cs.length,likeCount:ls.length,readers:Number(c?.readers||0)}}
function authorFor(c){if(!c||!c.ownerId)return null;if(c.ownerId==='system')return {id:'system',username:'katha_vistaar',name:'Katha Vistaar Team',followers:25000};const u=users.get(c.ownerId);return u?{id:u.id,username:u.username,name:u.name||u.username,followers:u.followers||0}:null}
function discoveryProfileFor(user){
 const pref=userPreferences.get(String(user?.id||''))||{};
 const interests=new Set(Array.isArray(pref.interests)?pref.interests.map(String):[]);
 const history=Array.isArray(user?.history)?user.history.map(String):[];
 const recent=new Set(history);
 const followedAuthors=new Set();
 for(const [authorId,rows] of follows.entries()) if(Array.isArray(rows)&&rows.includes(user?.id)) followedAuthors.add(String(authorId));
 const recentTypes=new Map();
 for(const cid of history.slice(0,30)){const c=content.get(cid);if(c)recentTypes.set(c.type,(recentTypes.get(c.type)||0)+1);}
 const preferredTypes=[...recentTypes.entries()].sort((a,b)=>b[1]-a[1]).map(x=>x[0]);
 const feedbackCategoryCounts=new Map(),feedbackTypeCounts=new Map(),crossFormatSignals=new Map();
 for(const e of (analyticsEvents.get(String(user?.id||''))||[]).slice(0,200)){
   const payload=e?.payload||{}; const action=String(e?.type||'');
   if(!['discovery_click','discovery_save','discovery_complete','discovery_cross_format_open'].includes(action))continue;
   const c=content.get(String(payload.contentId||''));
   if(c){feedbackCategoryCounts.set(String(c.category||''),(feedbackCategoryCounts.get(String(c.category||''))||0)+1);feedbackTypeCounts.set(String(c.type||''),(feedbackTypeCounts.get(String(c.type||''))||0)+1);}
   if(action==='discovery_cross_format_open'&&payload.seriesId)crossFormatSignals.set(String(payload.seriesId),(crossFormatSignals.get(String(payload.seriesId))||0)+1);
 }
 return {interests,history,recent,followedAuthors,recentTypes,preferredTypes,feedbackCategoryCounts,feedbackTypeCounts,crossFormatSignals,personalization:pref.privacy?.personalization!==false};
}
function discoveryScore(c,user,profile,mode='default'){
 const ageDays=Math.max(0,(Date.now()-Date.parse(c.updatedAt||c.createdAt||now()))/86400000);
 const engagement=contentEngagement(c.id);
 const author=String(c.ownerId||'');
 const category=String(c.category||'');
 let score=0;
 if(profile.interests.has(category)) score+=240;
 if(profile.followedAuthors.has(author)) score+=420;
 if(profile.recentTypes.has(c.type)) score+=Math.min(180,profile.recentTypes.get(c.type)*45);
 if(profile.feedbackTypeCounts?.has(c.type)) score+=Math.min(120,profile.feedbackTypeCounts.get(c.type)*35);
 if(profile.feedbackCategoryCounts?.has(category)) score+=Math.min(140,profile.feedbackCategoryCounts.get(category)*35);
 if(c.seriesId&&profile.crossFormatSignals?.has(String(c.seriesId))) score+=Math.min(180,profile.crossFormatSignals.get(String(c.seriesId))*45);
 if(profile.history.length===0 && c.ownerId==='system') score+=70;
 score+=Math.min(120,Math.log1p(Number(engagement.readers||0))*18);
 score+=Math.min(90,Number(engagement.likeCount||0)*2);
 score+=Math.min(80,Number(engagement.commentCount||0)*3);
 if(Number(engagement.ratingCount||0)>0) score+=Math.min(60,Number(engagement.rating||0)*10);
 score+=Math.max(0,70-ageDays*4);
 if(mode==='fresh') score+=Math.max(0,120-ageDays*8);
 if(mode==='following'&&profile.followedAuthors.has(author)) score+=250;
 if(mode==='cross_format'){
   const related=profile.history.map(id0=>content.get(id0)).filter(Boolean).some(x=>x.seriesId&&c.seriesId&&x.seriesId===c.seriesId&&x.type!==c.type);
   if(related) score+=500;
 }
 return score;
}
function rankedDiscovery(user,limit=20,mode='default'){
 const profile=discoveryProfileFor(user);
 const mine=new Set([...content.values()].filter(c=>c.ownerId===user.id).map(c=>c.id));
 return [...content.values()].filter(c=>c.status==='published'&&c.approval?.state==='approved'&&!mine.has(c.id)&&!profile.recent.has(c.id))
   .sort((a,b)=>discoveryScore(b,user,profile,mode)-discoveryScore(a,user,profile,mode))
   .slice(0,limit).map(publicContent);
}
function notifyUser(userId,event){const pref=userPreferences.get(String(userId))||{};const categories=pref.notifications||{};if(categories[event.category]===false)return null;const row={id:id(),category:event.category||'system',type:event.type||event.category||'system',titleKey:event.titleKey||null,bodyKey:event.bodyKey||null,messageParams:event.bodyParams||{},title:event.titleKey?null:String(event.title||''),body:event.bodyKey?null:String(event.body||''),deepLink:event.deepLink||null,createdAt:now(),read:false};setMap(notifications,userId,[row,...listMap(notifications,userId)].slice(0,200));return row}
function activeOffer(code,scope='all'){const o=monetization.get().offers.find(x=>x.id===String(code||'')&&x.active&&(!x.scope||x.scope==='all'||String(x.scope)===String(scope)));if(!o)return null;const t=Date.now();if(o.startsAt&&Date.parse(o.startsAt)>t)return null;if(o.endsAt&&Date.parse(o.endsAt)<t)return null;return o}
function messageRow(from,to,body,attachment=null){return {id:id(),from,to,body:String(body||'').slice(0,5000),attachment:attachment||null,createdAt:now(),read:false}}
function adminCanManageMonetization(c,permission='monetization.manage'){return adminHasPermission(c,permission)}
function adminCan(c,permission){return adminHasPermission(c,permission)}
function sanitizeTicketAttachment(input){
  if(!input||typeof input!=='object')return null;
  const mimeType=String(input.mimeType||input.type||'').toLowerCase();
  const data=String(input.data||'');
  if(!mimeType.startsWith('image/'))throw Object.assign(new Error('screenshot_image_required'),{code:'screenshot_image_required'});
  if(data.length>3*1024*1024)throw Object.assign(new Error('screenshot_too_large'),{code:'screenshot_too_large'});
  if(data && !/^data:image\/(png|jpeg|jpg|webp);base64,/i.test(data))throw Object.assign(new Error('invalid_screenshot_data'),{code:'invalid_screenshot_data'});
  return {id:'ATT-'+crypto.randomBytes(5).toString('hex').toUpperCase(),type:'screenshot',mimeType: mimeType==='image/jpg'?'image/jpeg':mimeType,data,createdAt:now()};
}
