function studioProjectValid(type,p){
 if(!p||typeof p!=='object')return false;
 if(!CONTENT_TYPES.includes(type))return false;
 const arr=(v,max)=>Array.isArray(v)&&v.length<=max;
 const str=(v,max)=>v===undefined||v===null||String(v).length<=max;
 if(type==='story'){
  if(p.outline!==undefined&&!arr(p.outline,200))return false;
  if(p.acts!==undefined&&!arr(p.acts,50))return false;
  if(p.scenes!==undefined&&!arr(p.scenes,500))return false;
  if(p.characters!==undefined&&!arr(p.characters,200))return false;
  return true;
 }
 if(type==='comic'){
  if(!arr(p.pages,200))return false;
  if(p.dpi!==undefined&&(!Number.isFinite(Number(p.dpi))||Number(p.dpi)<72||Number(p.dpi)>1200))return false;
  if(p.printPreset!==undefined&&!['screen','pdf_x4','png','print_master'].includes(String(p.printPreset)))return false;
  for(const page of p.pages){
   if(!page||typeof page!=='object'||!arr(page.panels,30))return false;
   if(page.layers!==undefined&&!arr(page.layers,40))return false;
   for(const panel of page.panels){
    if(!panel||typeof panel!=='object')return false;
    for(const k of ['x','y','w','h'])if(panel[k]!==undefined&&(!Number.isFinite(Number(panel[k]))||Number(panel[k])<0||Number(panel[k])>100))return false;
    if(panel.speechBubbles!==undefined&&!arr(panel.speechBubbles,20))return false;
    if(Array.isArray(panel.speechBubbles))for(const bubble of panel.speechBubbles){
     if(!bubble||typeof bubble!=='object'||!str(bubble.text,3000)||!str(bubble.language,20)||!str(bubble.type,40)||!str(bubble.font,120))return false;
     if(bubble.kerning!==undefined&&!Number.isFinite(Number(bubble.kerning)))return false;
     if(bubble.vectorAnchors!==undefined&&!arr(bubble.vectorAnchors,500))return false;
     if(bubble.bezierPaths!==undefined&&!arr(bubble.bezierPaths,500))return false;
     if(bubble.indicLigature!==undefined&&typeof bubble.indicLigature!=='boolean')return false;
    }
    if(panel.layers!==undefined&&!arr(panel.layers,40))return false;
    if(panel.bleedMm!==undefined&&(!Number.isFinite(Number(panel.bleedMm))||Number(panel.bleedMm)<0||Number(panel.bleedMm)>20))return false;
    if(panel.preflight!==undefined&&typeof panel.preflight!=='object')return false;
   }
  }
  return true;
 }
 if(type==='audio'){
  if(!arr(p.episodes,100))return false;
  if(p.sampleRate!==undefined&&!['44100','48000','96000'].includes(String(p.sampleRate)))return false;
  if(p.bitDepth!==undefined&&!['16','24','32'].includes(String(p.bitDepth)))return false;
  if(p.loudnessTarget!==undefined&&(!Number.isFinite(Number(p.loudnessTarget))||Number(p.loudnessTarget)<-30||Number(p.loudnessTarget)>-5))return false;
  if(p.truePeak!==undefined&&(!Number.isFinite(Number(p.truePeak))||Number(p.truePeak)>0||Number(p.truePeak)<-10))return false;
  if(p.phonemeLocked!==undefined&&typeof p.phonemeLocked!=='boolean')return false;
  if(p.smpteTimecode!==undefined&&!str(p.smpteTimecode,40))return false;
  for(const ep of p.episodes){
   if(!ep||typeof ep!=='object')return false;
   if(ep.tracks!==undefined&&!arr(ep.tracks,32))return false;
   if(ep.segments!==undefined&&!arr(ep.segments,500))return false;
   for(const tr of ep.tracks||[]){
    if(!tr||typeof tr!=='object')return false;
    for(const k of ['startMs','endMs','gainDb','pan'])if(tr[k]!==undefined&&!Number.isFinite(Number(tr[k])))return false;
    if(tr.assetId!==undefined&&tr.assetId!==null&&!safeMediaId(tr.assetId))return false;
    if(tr.effects!==undefined&&!arr(tr.effects,20))return false;
   }
  }
  return true;
 }
 if(type==='reel'){
  if(!arr(p.clips,60))return false;
  const fps=p.fps===undefined?30:Number(p.fps);
  if(![24,30,60].includes(fps))return false;
  if(p.resolution!==undefined&&!/^\d{3,4}x\d{3,4}$/.test(String(p.resolution)))return false;
  if(p.aspectRatio!==undefined&&!['9:16','16:9','1:1'].includes(String(p.aspectRatio)))return false;
  if(p.safeZones!==undefined&&!(p.safeZones===true||p.safeZones===false||(p.safeZones&&typeof p.safeZones==='object')))return false;
  if(p.smpteTimecode!==undefined&&!str(p.smpteTimecode,40))return false;
  if(p.timelineSnap!==undefined&&typeof p.timelineSnap!=='boolean')return false;
  if(p.scenes!==undefined&&!arr(p.scenes,100))return false;
  if(p.shots!==undefined&&!arr(p.shots,500))return false;
  for(const clip of p.clips){
   if(!clip||typeof clip!=='object')return false;
   if(clip.duration!==undefined&&(!Number.isFinite(Number(clip.duration))||Number(clip.duration)<=0))return false;
   if(clip.speed!==undefined&&(!Number.isFinite(Number(clip.speed))||Number(clip.speed)<=0||Number(clip.speed)>8))return false;
   if(clip.keyframes!==undefined&&!arr(clip.keyframes,200))return false;
   if(Array.isArray(clip.keyframes))for(const k of clip.keyframes){
    if(!k||typeof k!=='object'||!Number.isFinite(Number(k.frame))||Number(k.frame)<0)return false;
    if(k.easing!==undefined&&!['linear','cubic-bezier','ease-in','ease-out','elastic-snap','step','ease-in-out'].includes(String(k.easing)))return false;
    if(k.motionVector!==undefined&&(!k.motionVector||typeof k.motionVector!=='object'))return false;
   }
   if(clip.captions!==undefined&&!arr(clip.captions,100))return false;
   if(Array.isArray(clip.captions))for(const cap of clip.captions){if(!cap||typeof cap!=='object'||!str(cap.text,2000))return false;if(cap.start!==undefined&&(!Number.isFinite(Number(cap.start))||Number(cap.start)<0))return false;if(cap.end!==undefined&&(!Number.isFinite(Number(cap.end))||Number(cap.end)<0))return false;}
  }
  return true;
 }
 return false;
}

